INSERT INTO blog(title,slug,description,content,image_banner,seo_title,meta_description,num_view,created_date,update_date,archived) VALUES('Cẩm nang chọn giày sneaker','sports-cam-nang-sneaker','Hướng dẫn chọn giày phù hợp nhu cầu vận động.','<h2>Chọn giày theo hoạt động</h2><p>Kiểm tra độ vừa chân, bảng size riêng của hãng và mặt sân sử dụng. Nên thử cả hai chân, dành khoảng trống đầu ngón phù hợp.</p><p>Vệ sinh nhẹ nhàng, hong khô tự nhiên; không dùng thông số minh họa trong catalog để thay hướng dẫn của nhà sản xuất.</p>','/image/sports/sneaker.svg','Cẩm nang giày sneaker','Cẩm nang thể thao F6S.',0,NOW(6),NOW(6),b'0');
INSERT INTO catalog_release_item VALUES('sports-20261024','BLOG',5,LAST_INSERT_ID());
UPDATE product p JOIN catalog_release_item r ON r.record_id=p.id AND r.kind='PRODUCT' AND r.release_key='sports-20261024' SET p.code=CONCAT('F6S-SP',LPAD(CAST(p.id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(p.id AS CHAR))),'0'));
UPDATE product_detail d JOIN catalog_release_item r ON r.record_id=d.product_id AND r.kind='PRODUCT' AND r.release_key='sports-20261024' SET d.sku=CONCAT('F6S-SKU',LPAD(CAST(d.id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(d.id AS CHAR))),'0'));
UPDATE shoe_attribute SET code=CONCAT('F6S-',CASE kind WHEN 'BRAND' THEN 'TH' WHEN 'SOLE' THEN 'DE' ELSE 'CL' END,LPAD(CAST(id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(id AS CHAR))),'0')) WHERE code IS NULL;
COMMIT;
SELECT 'APPLIED: 25 new shoes, 250 variants. Old catalog retired, NOT deleted.' AS result;
END$$
CALL apply_sports_catalog()$$
DROP PROCEDURE apply_sports_catalog$$
DELIMITER ;
